def boundary_weld_candidate(original):
    """Copy an existing standalone fill, selecting only duplicated seam IDs.

    This opt-in construction changes only the final Merge by Distance selection.
    The already built/compacted graph, all payload attributes and every guard
    remain intact. No code runs during native evaluation or source editing.
    Unknown graph layouts fail explicitly instead of patching another weld.
    """
    if (not original.name.startswith(NAME) or 'Local assembly surface' in original.name
            or 'Shared local publication' in original.name):
        raise ValueError('Require a standalone curved separator surface')
    if original.get('st_boundary_weld_candidate'): return original
    name = original.name + ' / Boundary merge selection v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    def source(socket):
        if len(socket.links) != 1: raise ValueError('Unexpected standalone weld connection')
        return socket.links[0].from_node
