def replace_standalone_weld_references(roots=None, *, preserve_identity=False):
    """Opt in saved standalone calls; local once-only assembly is unchanged.

    Asset export can restrict the change to its reachable dependency graph and
    keep constructor cache names. Unrecognized standalone graphs still fail in
    boundary_weld_candidate rather than receiving a guessed replacement.
    """
    groups = bpy.data.node_groups
    if roots is not None:
        groups = set(); pending = list(roots)
        while pending:
            tree = pending.pop()
            if tree in groups: continue
            groups.add(tree)
            pending.extend(n.node_tree for n in tree.nodes if n.type == 'GROUP' and n.node_tree)
    originals = [tree for tree in groups if tree.name.startswith(NAME)
                 and 'Local assembly surface' not in tree.name
                 and 'Shared local publication' not in tree.name
                 and 'Boundary-only weld' not in tree.name
                 and not tree.get('st_boundary_weld_candidate')]
    rows = []
    for original in sorted(originals, key=lambda tree: tree.name):
        replacement = boundary_weld_candidate(original)
        name = original.name
        users = original.users
        if preserve_identity:
            import hashlib
            original['st_boundary_weld_original_name'] = name
            original.name = 'Diagnostic / Previous separator weld / '+hashlib.sha256(name.encode('utf8')).hexdigest()[:16]
            replacement.name = name
        rows.append(dict(previous=name, candidate=replacement.name, users=users))
        original.user_remap(replacement)
    return rows


def with_scoped_weld_references(root):
    """Copy only affected callers; keep the original shared network available."""
    from .curved_quad_fair_nodes import assign_group
    memo={};changes=[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.get('st_boundary_weld_candidate'):
            result=scoped_weld_reference_candidate(tree)
            if result!=tree:changes.append(tree.name)
        else:
            updates=[(node.name,visit(node.node_tree)) for node in tree.nodes if node.type=='GROUP' and node.node_tree]
            updates=[(name,child) for name,child in updates if child!=tree.nodes[name].node_tree]
            result=tree.copy() if updates else tree
            for name,child in updates:assign_group(result.nodes[name],child)
        memo[tree]=result
        return result
    result=visit(root)
    if not changes:raise ValueError('No unscoped selected separator welds found')
    return result,sorted(set(changes))


def _collar_fair(g, geometry, bundle_id, origin, *, steps=32):
    """Add one direct-quad boundary collar, then fair only its interior.

    Extruded boundary vertices retain the original pavement identities; the
    former boundary becomes an interior row. This removes the three-pinned-
    corner restriction at concave side/cap joins. All heights and outer
    coordinates remain fixed. A bounded neighbor average is a construction
    heuristic; the caller still requires positive cells and exact seams.
    """
    pos = g.node('GeometryNodeInputPosition', 'Separator collar coordinates').outputs[0]
    index = g.node('GeometryNodeInputIndex', 'New separator interior identity').outputs[0]
    neighbors = g.node('GeometryNodeInputMeshEdgeNeighbors', 'Only the existing separator boundary')
    extrude = g.node('GeometryNodeExtrudeMesh', 'One direct quad per existing boundary edge')
    extrude.mode = 'EDGES'
    g.set(geometry, extrude.inputs['Mesh'])
    g.set(g.compare(neighbors.outputs['Face Count'], 1), extrude.inputs['Selection'])
    extrude.inputs['Offset'].default_value = (0., 0., 0.)
    extrude.inputs['Offset Scale'].default_value = 0.
    collar = g.store(extrude.outputs['Mesh'], '_separator_outer', extrude.outputs['Top'], 'BOOLEAN')
    pinned = g.named('_separator_outer', 'BOOLEAN')
    key = g.switch(pinned, g.xyz(1., bundle_id, index), g.named('_separator_key', 'FLOAT_VECTOR'), 'VECTOR')
    collar = g.store(collar, '_separator_key', key, 'FLOAT_VECTOR')
    return _fair_fixed_boundary(g, collar, origin, steps=steps)


def _fair_fixed_boundary(g, collar, origin, *, steps):
    """Continue a bounded local average without adding another boundary row."""
    pos = g.node('GeometryNodeInputPosition', 'Separator fairing coordinates').outputs[0]
    pinned = g.named('_separator_outer', 'BOOLEAN')
    collar = bridge._position(g, collar, g.vector('SUBTRACT', pos, origin))
    begin = g.node('GeometryNodeRepeatInput', 'Fixed-boundary separator fairing' + ('' if steps == 32 else ' '+str(steps)))
    end = g.node('GeometryNodeRepeatOutput', 'Bounded local neighbor averaging')
    end.repeat_items.clear(); end.repeat_items.new('GEOMETRY', 'Geometry')
    begin.pair_with_output(end); begin.inputs['Iterations'].default_value = steps
    g.set(collar, begin.inputs['Geometry'])
    blur = g.node('GeometryNodeBlurAttribute', 'One topological neighbor average')
    blur.data_type = 'FLOAT_VECTOR'; blur.inputs['Iterations'].default_value = 1
    g.set(pos, blur.inputs['Value'])
    candidate = g.xyz(g.component(blur.outputs['Value'], 'X'), g.component(blur.outputs['Value'], 'Y'),
                      g.component(pos, 'Z'))
    moved = bridge._position(g, begin.outputs['Geometry'], g.switch(pinned, candidate, pos, 'VECTOR'))
    g.set(moved, end.inputs['Geometry'])
    return bridge._position(g, end.outputs['Geometry'], g.vector('ADD', pos, origin))


def _continue_until_positive(g, geometry, origin):
    """At most twelve more 64-pass batches, stopping at the first valid mesh.

    Only rejected 256-pass maps enter this fallback. Existing accepted meshes
    stay exact. No new collar, vertex, height or boundary freedom is introduced.
    The maximum is 1024 total passes. Denser boundaries shorten the physical
    reach of each neighbor average; the former 512-pass limit left seven
    inverted cells in a qualified free-chain boundary at half-metre sampling.
    This is a bounded construction attempt, never a reason to waive positivity.
    """
    begin=g.node('GeometryNodeRepeatInput','Bounded continuation for finer separator sampling')
    end=g.node('GeometryNodeRepeatOutput','Stop smoothing after positive cells')
    end.repeat_items.clear()
    for key,kind in (('Geometry','GEOMETRY'),('Positive','BOOLEAN'),('Steps','INT')):
        end.repeat_items.new(kind,key)
    begin.pair_with_output(end);begin.inputs['Iterations'].default_value=12
    g.set(geometry,begin.inputs['Geometry'])
    g.set(bridge._mesh_good(g,geometry),begin.inputs['Positive'])
    begin.inputs['Steps'].default_value=0
    advanced=_fair_fixed_boundary(g,begin.outputs['Geometry'],origin,steps=64)
    positive=begin.outputs['Positive']
    g.set(g.switch(positive,advanced,begin.outputs['Geometry'],'GEOMETRY'),end.inputs['Geometry'])
    g.set(g.switch(positive,bridge._mesh_good(g,advanced),True,'BOOLEAN'),end.inputs['Positive'])
    g.set(g.switch(positive,g.math('ADD',begin.outputs['Steps'],64),begin.outputs['Steps'],'INT'),end.inputs['Steps'])
    return end.outputs['Geometry'],end.outputs['Steps']


def _fair_boundary_heights(g, geometry, origin, steps):
    """Bounded convex height averaging after the planar mesh has settled.

    Planar fairing can compress a chart cell while leaving its cached height
    difference unchanged. Average only interior physical height and display Z,
    with the same positive neighbor weights. Exact boundary values remain
    pinned; XY, topology and public identities do not change. This preserves
    the elevation envelope but is not a general prescribed-slope solver.
    """
    begin=g.node('GeometryNodeRepeatInput','Settle interior heights on the final quad mesh')
    end=g.node('GeometryNodeRepeatOutput','Bounded height averaging with exact boundary values')
    end.repeat_items.clear();end.repeat_items.new('GEOMETRY','Geometry')
    begin.pair_with_output(end);begin.inputs['Iterations'].default_value=steps
    g.set(geometry,begin.inputs['Geometry'])
    pos=g.node('GeometryNodeInputPosition','Keep planar coordinates and use local elevation').outputs[0]
    original_z=g.component(origin,'Z')
    current=g.xyz(g.named('st_cn_height','FLOAT'),g.math('SUBTRACT',g.component(pos,'Z'),original_z))
    pinned=g.compare(g.component(g.named('_separator_key','FLOAT_VECTOR'),'X'),0.)
    blur=g.node('GeometryNodeBlurAttribute','One convex physical/display height average')
    blur.data_type='FLOAT_VECTOR';blur.inputs['Iterations'].default_value=1
    g.set(current,blur.inputs['Value'])
    next_values=g.switch(pinned,blur.outputs['Value'],current,'VECTOR')
    moved=g.store(begin.outputs['Geometry'],'_separator_next_height',next_values,'FLOAT_VECTOR')
    captured=g.named('_separator_next_height','FLOAT_VECTOR')
    moved=g.store(moved,'st_cn_height',g.component(captured,'X'),'FLOAT')
    moved=bridge._position(g,moved,g.xyz(g.component(pos,'X'),g.component(pos,'Y'),
        g.math('ADD',g.component(captured,'Y'),original_z)))
    g.set(moved,end.inputs['Geometry'])
    return end.outputs['Geometry']


def _head_identity(g, side, head):
    """One common original vertex chooses direction, without a spatial guess."""
    own = g.named('st_sb_original_vertex')
    table = bridge._position(g, head, g.xyz(own))
    lookup = g.node('GeometryNodeSampleNearest', 'Match original integer boundary identity'); lookup.domain = 'POINT'
    g.set(table, lookup.inputs['Geometry']); g.set(g.xyz(own), lookup.inputs['Sample Position'])
    found = g.compare(own, g.sample(table, own, lookup.outputs['Index'], 'INT'), kind='INT')
    neighbors = g.node('GeometryNodeInputMeshVertexNeighbors', 'Original side endpoints')
    found = g.all(found, g.compare(neighbors.outputs['Vertex Count'], 1))
    count = g.stat(side, found, output='Sum')
    identity = g.stat(side, g.math('MULTIPLY', found, own), output='Sum')
    return identity, g.compare(count, 1)


def _chain(g, geometry, first, side):
    """Order an existing open chain by accumulated edge length from its end.

    The graph has one route, so Shortest Edge Paths is simply an ordered
    length accumulation. It remains valid for bowed caps that turn backwards
    relative to a global projection axis. Connectivity and degree checks in
    the wire reader still reject branches, cycles or disconnected chains.
    """
    pos = g.node('GeometryNodeInputPosition', 'Original curved chain position').outputs[0]
    edge = g.node('GeometryNodeInputMeshEdgeVertices', 'Actual existing chain edges')
    paths = g.node('GeometryNodeInputShortestEdgePaths', 'Accumulate along the original boundary chain')
    g.set(g.compare(g.named('st_sb_original_vertex'), first, kind='INT'), paths.inputs['End Vertex'])
    g.set(g.vector('DISTANCE', edge.outputs['Position 1'], edge.outputs['Position 2']), paths.inputs['Edge Cost'])
    geometry = g.store(geometry, '_separator_physical', pos, 'FLOAT_VECTOR')
    geometry = bridge._position(g, geometry, g.xyz(paths.outputs['Total Cost']))
    wire, count, start, end, valid, query = bridge._wire(g, geometry, (1., 0., 0.), side)
    physical = bridge._position(g, wire, g.named('_separator_physical', 'FLOAT_VECTOR'))
    return physical, count, start, end, valid, lambda s, value=None: query(
        s, g.named('_separator_physical', 'FLOAT_VECTOR') if value is None else value)


def _free_cap_chart(g, side_a, side_b, tail):
    """Reclassify one new cap edge when the two original sides differ in parity.

    The complete perimeter must already be even. With one odd side and an odd
    free cap, transfer the cap edge incident to that side into its chart chain.
    Every edge and vertex remains in the same place, with the same identity;
    only the four-chain partition changes. Closed boundaries never use this.
    """
    own = g.named('st_sb_original_vertex')
    pos = g.node('GeometryNodeInputPosition', 'Exact free cap chart position').outputs[0]
    odd_a = g.compare(g.math('FLOORED_MODULO', g.math('SUBTRACT', bridge._size(g, side_a), 1.), 2.), 1.)
    odd_b = g.compare(g.math('FLOORED_MODULO', g.math('SUBTRACT', bridge._size(g, side_b), 1.), 2.), 1.)
    needed = g.all(g.boolean('XOR', odd_a, odd_b),
                   g.compare(g.math('FLOORED_MODULO', g.math('SUBTRACT', bridge._size(g, tail), 1.), 2.), 1.))
    side = g.switch(odd_a, side_b, side_a, 'GEOMETRY')
    first, unique = _head_identity(g, side, tail)
    edge = g.node('GeometryNodeInputMeshEdgeVertices', 'Transfer only the incident free cap edge')
    selected = g.either(*(g.compare(g.sample(tail, own, edge.outputs[name], 'INT'), first, kind='INT')
                           for name in ('Vertex Index 1', 'Vertex Index 2')))
    split = g.node('GeometryNodeSeparateGeometry', 'Partition the existing free cap'); split.domain = 'EDGE'
    g.set(tail, split.inputs['Geometry']); g.set(selected, split.inputs['Selection'])
    transferred = split.outputs['Selection']
    joined = g.store(bridge._join(g, side, transferred), '_separator_chart_position', pos, 'FLOAT_VECTOR')
    joined = bridge._position(g, joined, g.xyz(own))
    merge = g.node('GeometryNodeMergeByDistance', 'Join chart chains by exact original vertex identity')
    merge.inputs['Distance'].default_value = .1; g.set(joined, merge.inputs['Geometry'])
    joined = bridge._position(g, merge.outputs['Geometry'], g.named('_separator_chart_position', 'FLOAT_VECTOR'))
    valid = g.either(g.boolean('NOT', needed), g.all(unique,
        g.compare(bridge._size(g, transferred), 2.),
        g.compare(bridge._size(g, joined), g.math('ADD', bridge._size(g, side), 1.))))
    a = g.switch(g.all(needed, odd_a), side_a, joined, 'GEOMETRY')
    b = g.switch(g.all(needed, odd_b), side_b, joined, 'GEOMETRY')
    cap = g.switch(needed, tail, split.outputs['Inverted'], 'GEOMETRY')
    return a, b, cap, valid, needed


def _reference_weld_selection(g, pavement, separator):
    """Select all copies of actual seam identities, retaining the full payload.

    The reference can include the newly created free-cap vertices. Their
    identities are treated exactly like existing pavement seam vertices.
    Other reference vertices are unique and need no merge search. Agreement,
    weld counts, positive cells and oriented seams are still checked below.
    """
    index = g.node('GeometryNodeInputIndex', 'Reference seam identity').outputs[0]
    key = g.named('_bridge_key', 'FLOAT_VECTOR')
    copied = g.compare(g.component(key, 'X'), 0.)
    split = g.node('GeometryNodeSeparateGeometry', 'Actual separator seam copies')
    split.domain = 'POINT'
    g.set(separator, split.inputs['Geometry']); g.set(copied, split.inputs['Selection'])
    ids = bridge._position(g, split.outputs['Selection'], g.xyz(g.component(key, 'Y')))
    nearest = g.node('GeometryNodeSampleNearest', 'Match reference vertices to exact separator seam IDs')
    nearest.domain = 'POINT'
    g.set(ids, nearest.inputs['Geometry']); g.set(g.xyz(index), nearest.inputs['Sample Position'])
    selected = g.all(g.compare(bridge._size(g, ids), 0, 'GREATER_THAN'),
                     g.compare(g.sample(ids, g.component(key, 'Y'), nearest.outputs['Index'], 'INT'),
                               index, kind='INT'))
    name = '_separator_weld_selected'
    return (g.store(pavement, name, selected, 'BOOLEAN'),
            g.store(separator, name, copied, 'BOOLEAN'), g.named(name, 'BOOLEAN'))


def build(*, assembly=False, unequal_caps=False, free_cap=False, selective_weld=False, graded_tail=False,
          varying_boundary=False, boundary_height_steps=8, metric_height_steps=0,
          shared_construction=False, _construction_core=False, quality_refinement=False):
    """Build a standalone fill, or a local fill for checked network assembly.

    Assembly mode validates the boundary provenance, chart and local cells.
    Its caller MUST weld all fills with the pavement and check identity
    agreement, weld counts, positive cells and oriented seams on that result.
    This avoids repeating whole-network work for every separator. It has no
    combined Geometry output, so a local fill cannot masquerade as a checked
    standalone pavement assembly.

    The opt-in shared construction keeps standalone and assembly publication
    checks in their callers, while sharing the identical raw surface program.
    The private core is unchecked geometry and must never be published directly.
    """
    if shared_construction:
        if _construction_core:
            raise ValueError('A construction core cannot recursively wrap itself')
        from . import curved_separator_shared_nodes as shared
        return shared.build(assembly=assembly, unequal_caps=unequal_caps, free_cap=free_cap,
            selective_weld=selective_weld, graded_tail=graded_tail,
            varying_boundary=varying_boundary, boundary_height_steps=boundary_height_steps,
            metric_height_steps=metric_height_steps,quality_refinement=quality_refinement)
    if _construction_core and (not assembly or selective_weld):
        raise ValueError('Private construction has no standalone weld')
    if assembly and selective_weld:
        raise ValueError('Local assembly defers welding to its caller')
    if varying_boundary and graded_tail:
        raise ValueError('Choose one explicit separator height construction')
    if type(boundary_height_steps) is not int or not 0 <= boundary_height_steps <= 512:
        raise ValueError('Boundary-height fairing must have a bounded integer iteration count')
    if type(metric_height_steps) is not int or not 0 <= metric_height_steps <= 512:
        raise ValueError('Metric-height fairing must have a bounded integer iteration count')
    if metric_height_steps and not varying_boundary:
        raise ValueError('Metric-height refinement is explicit for varying boundary heights')
    if quality_refinement and (graded_tail or varying_boundary):
        raise ValueError('Pinned XY quality refinement currently requires a flat plateau')
    name = NAME + ' / Local assembly surface' if assembly else NAME
    if unequal_caps:
        name += ' / Unequal cap counts'
    if free_cap:
        name += ' / Free cap parity'
    if selective_weld:
        name += ' / Boundary-only weld'
    if graded_tail:
        name += ' / Graded tail cap'
    if varying_boundary:
        name += ' / Convex boundary-height blend candidate'
        name += ' / Pinned height fairing '+str(boundary_height_steps)
        if metric_height_steps:name += ' / Metric heights '+str(metric_height_steps)
    if _construction_core:
        name += ' / Shared construction core v1'
    if quality_refinement:name += ' / Pinned XY quality v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); g = _Nodes(tree)
    for name, kind, default in (
        *((name, 'NodeSocketGeometry', None) for name in ('Pavement', 'Side A', 'Side B', 'Head', 'Tail')),
        ('Cell Size', 'NodeSocketFloat', 1.), ('Bundle ID', 'NodeSocketInt', -1), ('Material', 'NodeSocketMaterial', None)):
        socket = tree.interface.new_socket(name=name, in_out='INPUT', socket_type=kind)
        if default is not None: socket.default_value = default
    outputs = [('Separator', 'NodeSocketGeometry'), ('Diagnostics', 'NodeSocketGeometry'), ('Valid', 'NodeSocketBool')]
    if not assembly:
        outputs.insert(0, ('Geometry', 'NodeSocketGeometry'))
    if _construction_core:
        # This value is scalar and evaluated on the original chains; it must
        # not become a field on the caller's final welded pavement.
        outputs.append(('Expected Weld', 'NodeSocketFloat'))
    for name, kind in outputs:
        tree.interface.new_socket(name=name, in_out='OUTPUT', socket_type=kind)
    inp = g.node('NodeGroupInput', 'Original pavement boundary chains')
    out = g.node('NodeGroupOutput', 'Checked conforming curved separator')
    pos = g.node('GeometryNodeInputPosition', 'Physical position').outputs[0]
    index = g.node('GeometryNodeInputIndex', 'Original mesh index').outputs[0]
    origin = g.sample(inp.outputs['Side A'], pos, 0, 'FLOAT_VECTOR')
    local = {name: bridge._position(g, inp.outputs[name], g.vector('SUBTRACT', pos, origin))
             for name in ('Side A', 'Side B', 'Head', 'Tail')}
    partition_valid, parity_transfer = True, False
    if free_cap:
        local['Side A'], local['Side B'], local['Tail'], partition_valid, parity_transfer = _free_cap_chart(
            g, local['Side A'], local['Side B'], local['Tail'])
    def mean(mesh):
        return g.xyz(*(g.stat(mesh, g.component(pos, k), output='Mean') for k in ('X', 'Y', 'Z')))
    axis = g.vector('NORMALIZE', g.vector('SUBTRACT', mean(local['Tail']), mean(local['Head'])))
    lateral = g.vector('CROSS_PRODUCT', (0., 0., 1.), axis)
    swap = g.compare(g.vector('DOT_PRODUCT', mean(local['Side A']), lateral),
                     g.vector('DOT_PRODUCT', mean(local['Side B']), lateral), 'GREATER_THAN')
    right = g.switch(swap, local['Side A'], local['Side B'], 'GEOMETRY')
    left = g.switch(swap, local['Side B'], local['Side A'], 'GEOMETRY')
    right_id, right_ok = _head_identity(g, right, local['Head'])
    left_id, left_ok = _head_identity(g, left, local['Head'])
    a, ac, a0, a1, av, aq = _chain(g, right, right_id, 0)
    b, bc, b0, b1, bv, bq = _chain(g, left, left_id, 1)
    head, hc, _, _, hv, _ = _chain(g, local['Head'], right_id, 2)
    tail_id = g.sample(a, g.named('st_sb_original_vertex'), g.math('SUBTRACT', ac, 1.), 'INT')
    tail, tc, _, _, tv, _ = _chain(g, local['Tail'], tail_id, 3)
    na, nb = g.math('SUBTRACT', ac, 1.), g.math('SUBTRACT', bc, 1.)
    head_count, tail_count = g.math('SUBTRACT', hc, 1.), g.math('SUBTRACT', tc, 1.)
    cap = g.math('MINIMUM', head_count, tail_count) if unequal_caps else head_count
    length = g.math('MULTIPLY', .5, g.math('ADD', g.math('SUBTRACT', a1, a0), g.math('SUBTRACT', b1, b0)))
    def endpoint(mesh, at): return g.sample(mesh, pos, at, 'FLOAT_VECTOR')
    width = g.math('MULTIPLY', .5, g.math('ADD',
        g.vector('DISTANCE', endpoint(head, 0), endpoint(head, head_count)),
        g.vector('DISTANCE', endpoint(tail, 0), endpoint(tail, g.math('SUBTRACT', tc, 1.)))))
    count_check = (g.all(g.compare(g.math('FLOORED_MODULO', tail_count, 2.), 0.),
                        g.compare(g.math('FLOORED_MODULO', head_count, 2.), 0.),
                        g.compare(g.math('MAXIMUM', head_count, tail_count), g.math('MULTIPLY', 5., cap), 'LESS_EQUAL'))
                   if unequal_caps else g.compare(hc, tc))
    checks = [partition_valid, right_ok, left_ok, av, bv, hv, tv, count_check, g.compare(cap, 4., 'GREATER_EQUAL'),
              g.compare(g.math('FLOORED_MODULO', cap, 2.), 0.), g.compare(width, 1e-5, 'GREATER_THAN')]
    for side, count, is_left in ((a, ac, False), (b, bc, True)):
        checks.extend(g.compare(g.vector('DISTANCE', endpoint(side, at), endpoint(end, corner if is_left else 0)), bridge.TOLERANCE, 'LESS_EQUAL')
                      for at, end, corner in ((0, head, head_count), (g.math('SUBTRACT', count, 1.), tail, tail_count)))
    original = bridge._join(g, a, b, head, tail)
    original_index = g.named('st_sb_original_vertex')
    reference = g.vector('SUBTRACT', g.sample(inp.outputs['Pavement'], pos, original_index, 'FLOAT_VECTOR'), origin)
    provenance = g.all(g.compare(original_index, 0., 'GREATER_EQUAL'),
                       g.compare(original_index, bridge._size(g, inp.outputs['Pavement']), 'LESS_THAN'),
                       g.compare(g.vector('DISTANCE', pos, reference), bridge.TOLERANCE, 'LESS_EQUAL'))
    checks.append(g.stat(original, provenance))
    z = g.component(endpoint(a, 0), 'Z')
    level = bridge._join(g, a, b, head) if graded_tail else original
    if not varying_boundary:
        checks.append(g.compare(g.stat(level, g.math('ABSOLUTE', g.math('SUBTRACT', g.component(pos, 'Z'), z)), output='Max'), 1e-7, 'LESS_EQUAL'))
    height = g.sample(inp.outputs['Side A'], g.named('st_cn_height', 'FLOAT'), 0, 'FLOAT')
    if varying_boundary:
        # Every boundary sample must carry its existing physical height. A
        # variable-height separator is an explicit branch, not a relaxation
        # of the common-plateau or graded-tail applicability checks.
        h = g.named('st_cn_height', 'FLOAT')
        source_h = g.sample(inp.outputs['Pavement'], h, original_index, 'FLOAT')
        checks.append(g.compare(g.stat(original, g.math('ABSOLUTE',
            g.math('SUBTRACT', h, source_h)), output='Max'), 1e-7, 'LESS_EQUAL'))
    if graded_tail:
        # This branch grades only one cap. The two member sides and opposite
        # cap retain their common plateau; a generally varying perimeter is
        # deliberately outside this construction's applicability.
        h = g.named('st_cn_height', 'FLOAT')
        source_h = g.sample(inp.outputs['Pavement'], h, original_index, 'FLOAT')
        checks.extend((
            g.compare(g.stat(level, g.math('ABSOLUTE', g.math('SUBTRACT', h, height)), output='Max'), 1e-7, 'LESS_EQUAL'),
            g.compare(g.stat(original, g.math('ABSOLUTE', g.math('SUBTRACT', h, source_h)), output='Max'), 1e-7, 'LESS_EQUAL'),
            g.compare(g.stat(tail, h, output='Max'), g.math('ADD', height, 1e-7), 'LESS_EQUAL'),
            g.compare(g.stat(tail, h, output='Min'), g.math('SUBTRACT', g.stat(inp.outputs['Pavement'], h, output='Min'), 1e-7), 'GREATER_EQUAL'),
            g.compare(g.stat(tail, g.component(pos, 'Z'), output='Max'), g.math('ADD', z, 1e-7), 'LESS_EQUAL')))
        for at in (0, tail_count):
            checks.append(g.compare(g.math('ABSOLUTE', g.math('SUBTRACT',
                g.sample(tail, h, at, 'FLOAT'), height)), 1e-7, 'LESS_EQUAL'))
    boundary_inputs_valid = g.all(*checks)
    def chart(mesh, first, last, offset):
        t = g.math('DIVIDE', g.math('SUBTRACT', g.named('_bridge_metric', 'FLOAT'), first), g.math('SUBTRACT', last, first))
        return bridge._position(g, mesh, g.xyz(g.math('MULTIPLY', length, t), offset))
    call = g.node('GeometryNodeGroup', 'Conforming rectangle with direct quad count transitions')
    call.node_tree = bridge.build(capped=True, exact_weld=True)
    for key, value in (('Boundary A', chart(a, a0, a1, 0.)), ('Boundary B', chart(b, b0, b1, width)),
                       ('End Intervals', cap), ('Axis', (1., 0., 0.)), ('Cell Size', inp.outputs['Cell Size'])):
        g.set(value, call.inputs[key])
    checks.append(call.outputs['Valid'])
    rectangle = call.outputs['Geometry']
    chart_valid = True
    if unequal_caps:
        from . import curved_separator_cap_nodes as cap_nodes
        rectangle, chart_valid = cap_nodes.construct(g, rectangle, length, width, head_count, tail_count)
        checks.append(chart_valid)
    t = g.math('DIVIDE', g.component(pos, 'X'), length); u = g.math('DIVIDE', g.component(pos, 'Y'), width)
    A = aq(g.math('ADD', a0, g.math('MULTIPLY', t, g.math('SUBTRACT', a1, a0))))
    B = bq(g.math('ADD', b0, g.math('MULTIPLY', t, g.math('SUBTRACT', b1, b0))))
    def cap_point(mesh, value=None):
        count = g.math('SUBTRACT', bridge._size(g, mesh), 1.)
        at = cap_nodes.rank(g, u, cap, count) if unequal_caps else g.math('MULTIPLY', u, cap)
        low = g.math('FLOOR', at)
        high = g.math('MINIMUM', g.math('ADD', low, 1.), count)
        left = endpoint(mesh, low) if value is None else g.sample(mesh, value, low, 'FLOAT_VECTOR')
        right = endpoint(mesh, high) if value is None else g.sample(mesh, value, high, 'FLOAT_VECTOR')
        return bridge._mix(g, left, right, g.math('SUBTRACT', at, low))
    H, T = cap_point(head), cap_point(tail)
    corners = bridge._mix(g, bridge._mix(g, endpoint(head, 0), endpoint(head, head_count), u),
                         bridge._mix(g, endpoint(tail, 0), endpoint(tail, tail_count), u), t)
    mapped = g.vector('SUBTRACT', g.vector('ADD', bridge._mix(g, A, B, u), bridge._mix(g, H, T, t)), corners)
    mapped_z = z
    if varying_boundary:
        # A rational convex blend of the four boundary traces. At an open
        # side only that side's weight is nonzero; at a corner its exact
        # original value is copied below. The nonnegative weights sum to one
        # in the interior, so height cannot undershoot or overshoot the
        # boundary envelope. This bounded heuristic has no numerical solve.
        square = lambda x: g.math('MULTIPLY', x, x)
        nt = g.math('SUBTRACT', 1., t); nu = g.math('SUBTRACT', 1., u)
        weights = (g.math('MULTIPLY', square(nu), g.math('MULTIPLY', square(t), square(nt))),
                   g.math('MULTIPLY', square(u), g.math('MULTIPLY', square(t), square(nt))),
                   g.math('MULTIPLY', square(nt), g.math('MULTIPLY', square(u), square(nu))),
                   g.math('MULTIPLY', square(t), g.math('MULTIPLY', square(u), square(nu))))
        denominator = g.math('MAXIMUM', 1e-20, g.math('ADD', g.math('ADD', weights[0], weights[1]),
                                                    g.math('ADD', weights[2], weights[3])))
        def convex(values):
            terms = [g.math('MULTIPLY', w, v) for w, v in zip(weights, values)]
            return g.math('DIVIDE', g.math('ADD', g.math('ADD', terms[0], terms[1]),
                                         g.math('ADD', terms[2], terms[3])), denominator)
        h = g.xyz(g.named('st_cn_height', 'FLOAT'))
        ah = aq(g.math('ADD', a0, g.math('MULTIPLY', t, g.math('SUBTRACT', a1, a0))), h)
        bh = bq(g.math('ADD', b0, g.math('MULTIPLY', t, g.math('SUBTRACT', b1, b0))), h)
        boundary_h = [g.component(v, 'X') for v in (ah, bh, cap_point(head, h), cap_point(tail, h))]
        rectangle = g.store(rectangle, '_separator_graded_height', convex(boundary_h), 'FLOAT')
        mapped_z = convex([g.component(v, 'Z') for v in (A, B, H, T)])
    if graded_tail:
        # A convex blend confined to two average separator widths upstream
        # of the cap. Quintic smoothstep has zero first/second derivatives at
        # both ends. No solve, clamping of an overshoot or resolution-dependent
        # iteration count is used for the height field.
        run = g.math('MINIMUM', length, g.math('MULTIPLY', 2., width))
        distance = g.math('MULTIPLY', g.math('SUBTRACT', 1., t), length)
        s = g.math('MINIMUM', 1., g.math('MAXIMUM', 0., g.math('DIVIDE', distance, run)))
        s2 = g.math('MULTIPLY', s, s); s3 = g.math('MULTIPLY', s2, s)
        smooth = g.math('MULTIPLY', s3, g.math('ADD', 10.,
            g.math('MULTIPLY', s, g.math('ADD', -15., g.math('MULTIPLY', 6., s)))))
        # Keep floating-point evaluation of the endpoint-flat polynomial a
        # convex weight, even if roundoff moves it just outside [0, 1].
        weight = g.math('MINIMUM', 1., g.math('MAXIMUM', 0., g.math('SUBTRACT', 1., smooth)))
        at = cap_nodes.rank(g, u, cap, tail_count) if unequal_caps else g.math('MULTIPLY', u, cap)
        low = g.math('FLOOR', at); high = g.math('MINIMUM', g.math('ADD', low, 1.), tail_count)
        low_h = g.sample(tail, g.named('st_cn_height', 'FLOAT'), low, 'FLOAT')
        high_h = g.sample(tail, g.named('st_cn_height', 'FLOAT'), high, 'FLOAT')
        tail_h = g.math('ADD', low_h, g.math('MULTIPLY', g.math('SUBTRACT', at, low), g.math('SUBTRACT', high_h, low_h)))
        graded_h = g.math('ADD', height, g.math('MULTIPLY', weight, g.math('SUBTRACT', tail_h, height)))
        mapped_z = g.math('ADD', z, g.math('MULTIPLY', weight, g.math('SUBTRACT', g.component(T, 'Z'), z)))
        rectangle = g.store(rectangle, '_separator_graded_height', graded_h, 'FLOAT')
    mapped = g.vector('ADD', g.xyz(g.component(mapped, 'X'), g.component(mapped, 'Y'), mapped_z), origin)
    source_side = g.named('_bridge_source_side'); source_index = g.named('_bridge_source_index')
    own = g.switch(g.compare(source_side, 0),
                   g.sample(b, g.named('st_sb_original_vertex'), source_index, 'INT'),
                   g.sample(a, g.named('st_sb_original_vertex'), source_index, 'INT'), 'INT')
    boundary = g.compare(source_side, 0., 'GREATER_EQUAL')
    for value, mesh in ((0., head), (1., tail)):
        at_cap = g.close(t, value, 1e-6)
        count = g.math('SUBTRACT', bridge._size(g, mesh), 1.)
        rank = g.math('ROUND', cap_nodes.rank(g, u, cap, count) if unequal_caps else g.math('MULTIPLY', u, cap))
        cap_owner = g.sample(mesh, g.named('st_sb_original_vertex'), rank, 'INT')
        own = g.switch(at_cap, own, cap_owner, 'INT'); boundary = g.either(boundary, at_cap)
    key = g.switch(boundary, g.xyz(1., inp.outputs['Bundle ID'], index), g.xyz(0., own), 'VECTOR')
    separator = g.store(rectangle, '_separator_key', key, 'FLOAT_VECTOR')
    separator = g.store(separator, '_separator_position', mapped, 'FLOAT_VECTOR')
    # Copy exact source coordinates after evaluating chart fields on the
    # rectangle. Capturing first avoids field reevaluation on the mapped mesh.
    separator = bridge._position(g, separator, g.named('_separator_position', 'FLOAT_VECTOR'))
    key = g.named('_separator_key', 'FLOAT_VECTOR')
    exact = g.sample(inp.outputs['Pavement'], pos, g.component(key, 'Y'), 'FLOAT_VECTOR')
    separator = bridge._position(g, separator, g.switch(g.compare(g.component(key, 'X'), 0.), pos, exact, 'VECTOR'))
    if varying_boundary:
        # A boundary collar turns the former boundary into an interior row.
        # Capture its exact physical heights now, just like its exact position.
        # Otherwise the rational blend's zero-denominator corner fallback
        # would survive as a false zero-height interior attribute after extrusion.
        separator = g.store(separator, '_separator_graded_height',
            g.switch(g.compare(g.component(key, 'X'), 0.),
                g.named('_separator_graded_height', 'FLOAT'),
                g.sample(inp.outputs['Pavement'], g.named('st_cn_height', 'FLOAT'),
                         g.component(key, 'Y'), 'FLOAT'), 'FLOAT'), 'FLOAT')
    original_positive = bridge._mesh_good(g, separator)
    collar = _collar_fair(g, separator, inp.outputs['Bundle ID'], origin)
    fair_steps = 32
    if unequal_caps:
        first_positive = bridge._mesh_good(g, collar)
        longer = _collar_fair(g, separator, inp.outputs['Bundle ID'], origin, steps=64)
        # A long, tapered median can need more local propagation than 64
        # passes. Keep accepted earlier meshes verbatim and use bounded
        # continuation only after they fail. This remains a heuristic:
        # positivity and exact seam/weld checks below must still accept it.
        second_positive = bridge._mesh_good(g, longer)
        last = _collar_fair(g, separator, inp.outputs['Bundle ID'], origin, steps=96)
        third_positive = bridge._mesh_good(g, last)
        # Finer sampling shortens each averaging step's physical reach.
        # Continue the existing collar to a total of 256 passes, without
        # another extrusion or a relaxation of any publication check.
        continued = _fair_fixed_boundary(g, last, origin, steps=160)
        fourth_positive = bridge._mesh_good(g, continued)
        final, extra_steps = _continue_until_positive(g, continued, origin)
        continued = g.switch(fourth_positive, final, continued, 'GEOMETRY')
        last = g.switch(third_positive, continued, last, 'GEOMETRY')
        longer = g.switch(second_positive, last, longer, 'GEOMETRY')
        collar = g.switch(first_positive, longer, collar, 'GEOMETRY')
        last_steps = g.switch(third_positive,
            g.switch(fourth_positive,g.math('ADD',256,extra_steps),256,'INT'),96,'INT')
        fair_steps = g.switch(first_positive, g.switch(second_positive, last_steps, 64, 'INT'), 32, 'INT')
    separator = g.switch(original_positive, collar, separator, 'GEOMETRY')
    # The fairing happens in a small local frame. Restore the actual outer
    # pavement coordinates after adding the origin to avoid roundoff at seams.
    separator = bridge._position(g, separator, g.switch(g.compare(g.component(key, 'X'), 0.), pos, exact, 'VECTOR'))
    if graded_tail or varying_boundary:
        height = g.switch(g.compare(g.component(key, 'X'), 0.),
            g.named('_separator_graded_height', 'FLOAT'),
            g.sample(inp.outputs['Pavement'], g.named('st_cn_height', 'FLOAT'), g.component(key, 'Y'), 'FLOAT'), 'FLOAT')
    separator = g.store(separator, 'st_cn_height', height, 'FLOAT')
    quality_diagnostics=()
    if quality_refinement:
        from . import curved_separator_quality_nodes
        quality=g.node('GeometryNodeGroup','Optional flat separator spacing improvement')
        quality.node_tree=curved_separator_quality_nodes.build()
        g.set(separator,quality.inputs['Geometry']);separator=quality.outputs['Geometry']
        quality_diagnostics=tuple((name,quality.outputs[key],kind) for name,key,kind in (
            ('quality_applied','Applied','BOOLEAN'),('quality_blend','Blend','FLOAT'),
            ('quality_before_ratio','Before Ratio','FLOAT'),('quality_after_ratio','After Ratio','FLOAT')))
    if varying_boundary and boundary_height_steps:
        separator = _fair_boundary_heights(g, separator, origin, boundary_height_steps)
    metric_valid=True
    if metric_height_steps:
        from .curved_separator_metric_height_nodes import fair
        separator,metric_valid=fair(g,separator,origin,metric_height_steps)
        checks.append(metric_valid)
    if varying_boundary and (boundary_height_steps or metric_height_steps):
        # Re-copy seam values to eliminate roundoff from the local-frame shift.
        seam = g.compare(g.component(key, 'X'), 0.)
        separator = bridge._position(g, separator, g.switch(seam, pos, exact, 'VECTOR'))
        separator = g.store(separator, 'st_cn_height', g.switch(seam,
            g.named('st_cn_height', 'FLOAT'), g.sample(inp.outputs['Pavement'],
            g.named('st_cn_height', 'FLOAT'), g.component(key, 'Y'), 'FLOAT'), 'FLOAT'), 'FLOAT')
    if graded_tail or varying_boundary:
        actual_h = g.named('st_cn_height', 'FLOAT')
        ceiling = (g.stat(original, actual_h, output='Max') if varying_boundary else
                   g.sample(inp.outputs['Side A'], actual_h, 0, 'FLOAT'))
        floor = g.stat(original, actual_h, output='Min')
        checks.append(g.stat(separator, g.all(
            g.compare(actual_h, g.math('SUBTRACT', floor, 1e-7), 'GREATER_EQUAL'),
            g.compare(actual_h, g.math('ADD', ceiling, 1e-7), 'LESS_EQUAL'))))
    separator = g.store(separator, 'st_bundle_id', inp.outputs['Bundle ID'], 'INT', 'FACE')
    separator = g.store(separator, 'st_separator_closure', True, 'BOOLEAN', 'FACE')
    separator = g.store(separator, '_bridge_key', key, 'FLOAT_VECTOR')
    material = g.node('GeometryNodeSetMaterial', 'Separator pavement material')
    g.set(separator, material.inputs['Geometry']); g.set(inp.outputs['Material'], material.inputs['Material'])
    separator = material.outputs['Geometry']
    if assembly:
        if _construction_core:
            positive = True  # Replaced by each caller's original final check.
            seam_diagnostics = ()
            expected = g.math('SUBTRACT', g.math('ADD', g.math('ADD', ac, bc), g.math('ADD', hc, tc)), 4.)
            g.set(expected, out.inputs['Expected Weld'])
        else:
            positive = bridge._mesh_good(g, separator)
            checks.append(positive)
            seam_diagnostics = (('assembly_checks_deferred', True, 'BOOLEAN'),)
        geometries = (('Separator', separator),)
    else:
        pavement = g.store(inp.outputs['Pavement'], '_bridge_key', g.xyz(0., index), 'FLOAT_VECTOR')
        weld_separator = separator
        selection = None
        if selective_weld:
            pavement, weld_separator, selection = _reference_weld_selection(g, pavement, separator)
        combined = bridge._join(g, pavement, weld_separator)
        welded, agreement = bridge._weld(g, combined, exact_reference=True, merge_selection=selection)
        expected = g.math('SUBTRACT', g.math('ADD', g.math('ADD', ac, bc), g.math('ADD', hc, tc)), 4.)
        reduction = g.math('SUBTRACT', bridge._size(g, combined), bridge._size(g, welded))
        # The original pavement vertices keep their positions bit for bit.
        key = g.named('_bridge_key', 'FLOAT_VECTOR')
        exact = g.sample(inp.outputs['Pavement'], pos, g.component(key, 'Y'), 'FLOAT_VECTOR')
        welded = bridge._position(g, welded, g.switch(g.compare(g.component(key, 'X'), 0.), pos, exact, 'VECTOR'))
        positive = bridge._mesh_good(g, welded); oriented = closure._oriented_seams(g, welded)
        checks.extend((agreement, g.compare(expected, reduction), positive, oriented))
        seam_diagnostics = (('oriented', oriented, 'BOOLEAN'), ('agreement', agreement, 'BOOLEAN'),
                            ('expected_weld', expected, 'INT'), ('actual_weld', reduction, 'INT'))
        geometries = (('Geometry', welded), ('Separator', separator))
    valid = g.all(*checks)
    record = g.node('GeometryNodeMeshLine', 'Separator construction diagnostics'); record.inputs['Count'].default_value = 1
    status = record.outputs['Mesh']
    for name, value, kind in (('valid', valid, 'BOOLEAN'), ('bridge_valid', call.outputs['Valid'], 'BOOLEAN'),
                             ('boundary_inputs_valid', boundary_inputs_valid, 'BOOLEAN'),
                             ('cap_chart_valid', chart_valid, 'BOOLEAN'),
                             ('free_cap_edge_transfer', parity_transfer, 'BOOLEAN'),
                             ('head_intervals', head_count, 'INT'), ('tail_intervals', tail_count, 'INT'),
                             ('collar_used', g.boolean('NOT', original_positive), 'BOOLEAN'),
                             ('fairing_steps', g.switch(original_positive, fair_steps, 0, 'INT'), 'INT'),
                             *((('height_fairing_steps', boundary_height_steps, 'INT'),) if varying_boundary else ()),
                             *((('metric_height_steps',metric_height_steps,'INT'),
                                ('metric_weights_valid',metric_valid,'BOOLEAN')) if metric_height_steps else ()),
                             ('bridge_code', call.outputs['Diagnostic Code'], 'INT'), ('positive', positive, 'BOOLEAN'),
                             *quality_diagnostics,*seam_diagnostics):
        status = g.store(status, 'st_separator_'+name, value, kind)
    for name, geometry in geometries:
        g.set(geometry if _construction_core else g.switch(valid, None, geometry, 'GEOMETRY'), out.inputs[name])
    g.set(valid, out.inputs['Valid']); g.set(status, out.inputs['Diagnostics'])
    if _construction_core:
        tree['st_unchecked_separator_construction'] = 1
    return tree
